 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in {v for row in grid for v in row if v != bg}:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in pts:
                if (r + dr, c + dc) not in pts:
                    continue
                nr, nc = r + 2 * dr, c + 2 * dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg):
                    continue
                while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                    out[nr][nc] = color
                    nr, nc = nr + dr, nc + dc
                return out
    return out
